function journeyCanvas(){
 const n=stops.length;if(!n)return `<div class="canvas-empty glass"><h2>Your journey starts <em>here.</em></h2><p>Give your photos a place. We’ll connect the moments.</p><button class="button dark" data-action="organize">Place your photos ${icon('pin')}</button></div>`;
 const mobile=window.matchMedia('(max-width:700px)').matches;
 const h=mobile?Math.max(330,220+(n-1)*152):620,w=mobile?360:Math.max(1200,230*n);
 const desktop=[[115,414],[352,250],[555,382],[775,230],[1030,140]];
 const phone=[[68,123],[292,275],[68,427],[292,579],[68,731]];
 const pts=stops.map((s,i)=>{if(n===5)return (mobile?phone:desktop)[i];if(mobile)return [i%2?292:68,123+i*((h-220)/Math.max(1,n-1))];return [100+i*((w-230)/Math.max(1,n-1)),315+Math.sin(i*1.85)*105];});
 let path=`M ${pts[0][0]} ${pts[0][1]}`;
 pts.slice(1).forEach(([x,y],j)=>{
  const [px,py]=pts[j];
  // A single flowing route passes through photo centers. Equal vertical
  // tangents join adjacent segments; there are no extra loops between stops.
  const bend=(y-py)*0.9;
  path+=mobile
   ? ` C ${px} ${py+bend}, ${x} ${y-bend}, ${x} ${y}`
   : ` C ${px+105} ${py}, ${x-105} ${y}, ${x} ${y}`;
 });
 return `<svg class="memory-path" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="journey-line" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stop-color="#7ea899"/><stop offset=".48" stop-color="#a9c5a3"/><stop offset="1" stop-color="#d2b57c"/></linearGradient><filter id="route-soft"><feGaussianBlur stdDeviation="5"/></filter></defs><path d="${path}" fill="none" stroke="#88a69c" stroke-width="18" opacity=".13" transform="translate(0 16)" filter="url(#route-soft)"/><path d="${path}" fill="none" stroke="#ffffff" stroke-width="7" opacity=".75"/><path d="${path}" fill="none" stroke="url(#journey-line)" stroke-width="2.6" stroke-dasharray="0.1 7.5" stroke-linecap="round"/>${pts.map(([x,y],i)=>`<ellipse cx="${x}" cy="${y+13}" rx="${mobile?28:39}" ry="${mobile?9:12}" fill="#749887" opacity=".09"/><circle cx="${x}" cy="${y}" r="${i===0||i===n-1?8:6}" fill="${i===0?'#638c7a':i===n-1?'#bd9c61':'#99b49b'}" stroke="#fff" stroke-width="4"/>`).join('')}</svg>
 ${stops.map((s,i)=>{const [x,y]=pts[i],end=i===n-1;return `<div class="journey-point ${i%2?'point-right':'point-left'} ${i===0?'start-point':''} ${end?'end-point':''} ${s.id===selectedId?'selected-point':''}" style="--x:${x/w*100}%;--y:${y/h*100}%;--tilt:${[-5,4,-4,5,-3][i%5]}deg"><button class="memory-photo glass" data-action="stop" data-id="${esc(s.id)}" aria-label="Open ${esc(s.name)} photos and notes"><img src="${esc(s.photos[0].src)}" alt="${esc(s.name)}"><span class="memory-photo-count">${icon('photos')}${s.photos.length}</span>${s.photos.length>1?'<span class="photo-edge"></span>':''}</button><span class="point-stem"></span><button class="point-label" data-action="stop" data-id="${esc(s.id)}"><small>${`${String(i+1).padStart(2,'0')} · ${i===0?'THE BEGINNING':end?'THE LAST STOP':'ALONG THE WAY'}`}</small><strong>${esc(s.name)}</strong><span>${date(s.takenAt)}</span></button>${s.highlight?`<button class="point-memory glass" data-action="stop" data-id="${esc(s.id)}">${i===1?'♡':'✧'} ${esc(s.highlight)} ${icon('diagonal')}</button>`:''}</div>`}).join('')}
 `;
}

function chapter(s,i){return `<article class="chapter"><span class="chapter-step glass">${i===0?icon('flag'):String(i+1).padStart(2,'0')}</span><div class="chapter-head"><div><span class="eyebrow">${startEnd(i)} <span class="day"> · ${date(s.takenAt)}</span></span><h2>${esc(s.name)}</h2></div><button class="open-circle glass" data-action="stop" data-id="${esc(s.id)}" aria-label="Open ${esc(s.name)} photos and notes">${icon('diagonal')}</button></div><div class="chapter-photos ${s.photos.length>1?'multi':''}">${s.photos.slice(0,2).map(p=>`<button data-action="stop" data-id="${esc(s.id)}" aria-label="Explore ${esc(s.name)}"><img src="${esc(p.src)}" alt="${esc(p.caption||s.name)}" loading="lazy"></button>`).join('')}<span class="photo-count">${icon('photos')}${count(s.photos.length,'photo')}</span></div>${s.notes.length?`<button class="chapter-note" data-action="stop" data-id="${esc(s.id)}" style="display:block;width:100%;text-align:left"><span class="quote-mark">“</span>${esc(s.notes[0])}</button>`:`<button class="add-note-inline" data-action="edit-note" data-id="${esc(s.id)}">${icon('edit')} What stayed with you?</button>`}<div class="chapter-foot">${s.highlight?`<span class="highlight">✧ ${esc(s.highlight)}</span>`:`<span>${count(s.photos.length,'photo')} kept together</span>`}<span>${s.source==='Placed by you'?'Placed by you':s.photos.length>1?'One place, '+s.photos.length+' memories':date(s.takenAt,{hour:'numeric',minute:'2-digit'})}</span></div></article>`;}
