function initMap(){if(map){map.remove();map=null}if(!window.L){$('#route-map').innerHTML='<div class="map-error">The map couldn’t load. Your photos and notes are still available in the story.</div>';return}map=L.map('route-map',{zoomControl:false,scrollWheelZoom:false,attributionControl:true,dragging:true});tileLayer(map);mapLayers=L.layerGroup().addTo(map);fitMap();renderMapMarkers();map.on('zoomend',renderMapMarkers);map.whenReady(()=>map.invalidateSize());}
function fitMap(){if(!map)return;if(!stops.length)map.setView([40.631,14.52],11);else if(stops.length===1)map.setView([stops[0].gps.lat,stops[0].gps.lng],14);else map.fitBounds(stops.map(s=>[s.gps.lat,s.gps.lng]),{paddingTopLeft:[48,90],paddingBottomRight:[48,75],maxZoom:14});}
function renderMapMarkers(){if(!mapLayers)return;mapLayers.clearLayers();markers=[];if(stops.length>1){L.polyline(stops.map(s=>[s.gps.lat,s.gps.lng]),{color:'#fff',weight:7,opacity:.95}).addTo(mapLayers);L.polyline(stops.map(s=>[s.gps.lat,s.gps.lng]),{color:'#527c5a',weight:2.5,dashArray:'5,8',opacity:.9}).addTo(mapLayers)}const placed=[];stops.forEach((s,i)=>{const actual=map.latLngToLayerPoint([s.gps.lat,s.gps.lng]);let offset=0;for(const candidate of [0,-76,76,-145,145]){const box={x:actual.x,y:actual.y+candidate};if(!placed.some(prev=>Math.abs(prev.x-box.x)<68&&Math.abs(prev.y-box.y)<85)){offset=candidate;break;}}placed.push({x:actual.x,y:actual.y+offset});if(offset){const endpoint=map.layerPointToLatLng([actual.x,actual.y+offset]);L.polyline([[s.gps.lat,s.gps.lng],endpoint],{color:'#7d9878',weight:1.3,dashArray:'2,3',opacity:.8}).addTo(mapLayers);L.circleMarker([s.gps.lat,s.gps.lng],{radius:3,color:'#fff',weight:1,fillColor:'#5d8154',fillOpacity:1}).addTo(mapLayers);}const p=s.photos[0],type=i===0?'START':i===stops.length-1?'FINISH':'';const html=`<div class="pin-wrap"><div class="photo-pin"><img src="${esc(p.src)}" alt=""><span class="pin-badge">${s.photos.length}</span></div><span class="pin-label">${type?`<span class="pin-type">${type}</span>`:''}${esc(s.name)}</span></div>`;const marker=L.marker([s.gps.lat,s.gps.lng],{icon:L.divIcon({className:'route-marker'+(s.id===selectedId?' selected':''),html,iconSize:[62,82],iconAnchor:[31,26-offset]}),title:`${type?type+' · ':''}${s.name} · ${count(s.photos.length,'photo')} · ${s.notes.length?'has notes':'add a note'}`,keyboard:true}).addTo(mapLayers).on('click',()=>openStop(s.id));if(showMapNotes&&s.notes.length)marker.bindTooltip(esc(s.notes[0].slice(0,78))+(s.notes[0].length>78?'…':''),{permanent:s.id===selectedId,direction:'top',offset:[0,-48+offset],className:'note-tooltip'});markers.push(marker)});}
function openStop(id){const s=stops.find(s=>s.id===id);if(!s)return;selectedId=id;renderMapMarkers();const d=$('#stop-sheet');const i=stops.indexOf(s);d.setAttribute('aria-label',`${s.name} photos and notes`);d.innerHTML=`<div class="sheet-scroll"><div class="sheet-hero"><img src="${esc(s.photos[0].src)}" alt="${esc(s.name)}"><span class="sheet-grabber"></span><button class="sheet-close icon-button glass" data-action="close-stop" aria-label="Close stop details">${icon('close')}</button><div class="sheet-hero-bottom"><div><span class="eyebrow">${startEnd(i)} · ${date(s.takenAt)}</span><h2>${esc(s.name)}</h2></div><span class="photo-count glass">${icon('photos')}${count(s.photos.length,'photo')}</span></div></div><div class="sheet-content"><div class="sheet-meta">${icon('pin')}<span>${Math.abs(s.gps.lat).toFixed(4)}° ${s.gps.lat<0?'S':'N'}, ${Math.abs(s.gps.lng).toFixed(4)}° ${s.gps.lng<0?'W':'E'}</span><span>· ${esc(s.source)}</span></div><div class="sheet-photos">${s.photos.map(p=>`<button data-action="photo" data-id="${esc(p.id)}" aria-label="View ${esc(p.caption||'photo')}" title="${esc(p.caption||'View photo')}"><img src="${esc(p.src)}" alt="${esc(p.caption||s.name)}"></button>`).join('')}${ownJourney()?`<button class="glass" data-action="add-to-stop" data-id="${esc(s.id)}" aria-label="Add a photo to this stop">${icon('upload')}</button>`:''}</div><div class="sheet-note glass"><div class="sheet-note-head"><span>A NOTE TO REMEMBER</span>${ownJourney()?`<button data-action="edit-note" data-id="${esc(s.id)}">${icon('edit')}${s.notes.length?'Edit':'Add note'}</button>`:''}</div><p>${s.notes.length?'“'+esc(s.notes.join('\n\n'))+'”':'What made this place yours?'}</p>${s.highlight?`<span class="highlight">✧ ${esc(s.highlight)}</span>`:''}</div><div class="sheet-footer"><button data-action="show-on-map" data-id="${esc(s.id)}">${icon('map')}Back to journey</button><span class="sheet-count">${i+1} / ${stops.length}</span>${i<stops.length-1?`<button data-action="stop" data-id="${esc(stops[i+1].id)}">Next stop ${icon('arrow')}</button>`:`<button data-action="stop" data-id="${esc(stops[0].id)}">Back to start ${icon('arrow')}</button>`}</div></div></div>`;if(!d.open)d.showModal();}
function modal(title,body,footer=''){$('#editor').classList.remove('story-modal','comments-sheet','likes-sheet','gallery-sheet');if(locationMap){locationMap.remove();locationMap=null}const d=$('#editor');d.setAttribute('aria-label',title);d.innerHTML=`<div class="modal-frame"><header class="modal-header"><span class="eyebrow">ATLAS</span><button class="close" data-action="close-editor" aria-label="Close dialog">×</button></header><div class="modal-content">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</div>`;if(!d.open)d.showModal();}
function openNote(id,inDraft=false){editingDraft=inDraft;const j=activeJourney(),s=getStops(j).find(s=>s.id===id);if(!s)return;modal('Edit stop note',`<h2>A note for this place.</h2><form id="note-form" class="note-editor"><div class="field"><label for="stop-name">Place name</label><input id="stop-name" maxlength="80" value="${esc(s.name)}" required></div><div class="field"><label for="stop-note">Your note</label><textarea id="stop-note" rows="4" maxlength="2000" placeholder="The view. The coffee. The unexpected little detour…">${esc(s.notes.join('\n\n'))}</textarea></div><div class="field"><label for="stop-highlight">The highlight</label><input id="stop-highlight" list="highlight-options" maxlength="65" value="${esc(s.highlight)}" placeholder="e.g. My favorite view"><datalist id="highlight-options"><option>My favorite view</option><option>Best coffee</option><option>Go early</option><option>Hidden gem</option><option>Don’t miss sunset</option></datalist></div></form>`,`<button class="small-action" data-action="${inDraft?'organize-draft':'close-editor'}">Cancel</button><button class="button dark" form="note-form" type="submit">Save memory ${icon('check')}</button>`);$('#note-form').onsubmit=e=>{e.preventDefault();setStopAnnotation(j,s,{name:$('#stop-name').value.trim()||s.name,notes:[$('#stop-note').value.trim()].filter(Boolean),highlight:$('#stop-highlight').value.trim()});persist();if(inDraft){$('#editor').close();composerPlaces();toast('Memory saved to this stop')}else{$('#editor').close();render();openStop(s.id);toast('Memory saved to this stop')}};}
function organize(isDraft=false){if(isDraft){editingDraft=true;createStep=2;composerPlaces();return}editingDraft=isDraft;const j=activeJourney(),groups=getStops(j),unplaced=j.photos.filter(p=>!validGPS(p.gps));modal(isDraft?'Place your journey photos':'Organize journey photos',`${isDraft?stepper():''}<span class="eyebrow">PHOTOS → PLACES → MEMORIES</span><h2>Every photo.<br><em>In its place.</em></h2><p class="modal-description">Nearby photos become one stop. Add a note to the place, and keep the whole moment together.</p><div class="organize-summary"><span class="status-chip">${icon('pin')}${count(groups.length,'stop')}</span><span class="status-chip">${count(j.photos.length-unplaced.length,'photo')} placed</span>${unplaced.length?`<span class="status-chip warning">${unplaced.length} need a location</span>`:''}</div>${uploadMarkup()}<div class="group-radius"><label for="group-radius">Group photos within</label><select id="group-radius"><option value="50" ${j.radius===50?'selected':''}>50 meters</option><option value="150" ${j.radius===150?'selected':''}>150 meters</option><option value="500" ${j.radius===500?'selected':''}>500 meters</option></select></div>${unplaced.length?`<section class="group-box"><div class="group-title"><strong>A place is missing</strong><small>No location tag</small></div><div class="unplaced-grid">${unplaced.map(p=>`<button class="unplaced-card" data-action="locate" data-id="${esc(p.id)}"><img src="${esc(p.src)}" alt="${esc(p.caption||'Unplaced photo')}"><span>＋ Add location</span></button>`).join('')}</div></section>`:''}${groups.map(s=>`<section class="group-box"><div class="group-title"><div><strong>${esc(s.name)}</strong><br><small>${count(s.photos.length,'photo')} · ${esc(s.source)}</small></div><button class="small-action" data-action="${isDraft?'draft-note':'edit-note'}" data-id="${esc(s.id)}">${icon('edit')}${s.notes.length?'Edit note':'Add note'}</button></div><div class="group-thumbs">${s.photos.map(p=>`<button data-action="locate" data-id="${esc(p.id)}" aria-label="Edit location for ${esc(p.caption||'photo')}"><img src="${esc(p.src)}" alt="${esc(p.caption||s.name)}">${p.id===j.cover?'<span class="cover-badge">COVER</span>':''}</button>`).join('')}</div>${s.notes.length?`<p class="helper" style="margin-top:10px">“${esc(s.notes[0].slice(0,110))}${s.notes[0].length>110?'…':''}”</p>`:''}</section>`).join('')}<p class="helper">Location tags are read on your device. Photos and changes are saved locally.</p>`,`${isDraft?'<button class="small-action" data-action="create-back">← Photos</button>':'<span class="muted">Your photos stay together.</span>'}<button class="button dark" data-action="${isDraft?'create-next':'done-organize'}">${isDraft?'Add your story':'Done'} ${icon('arrow')}</button>`);bindUpload();$('#group-radius').onchange=e=>{j.radius=Number(e.target.value);if(!isDraft)render();organize(isDraft)};}
function uploadMarkup(){return `<label class="upload-zone" id="drop-zone">${icon('upload')}<span>Add your photos<small>JPG, PNG, WebP · up to 15 MB each</small></span><input type="file" id="photo-upload" accept="image/jpeg,image/png,image/webp" multiple ${busy?'disabled':''}></label>`;}
function bindUpload(targetStop=null){const input=$('#photo-upload');if(!input)return;input.onchange=e=>loadPhotos(e.target.files,targetStop);const zone=$('#drop-zone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragging')};zone.ondragleave=()=>zone.classList.remove('dragging');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragging');loadPhotos(e.dataTransfer.files,targetStop)}}
async function loadPhotos(files,targetStop=null){if(busy)return;busy=true;const target=activeJourney();const input=$('#photo-upload');if(input)input.disabled=true;toast('Reading photo locations…');let added=0,rejected=0;for(const file of [...files].slice(0,40)){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024){rejected++;continue}try{const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});await new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=reject;img.src=src});let meta={};try{meta=await window.exifr?.parse(file)||{}}catch{}const gps=validGPS({lat:meta.latitude,lng:meta.longitude})?{lat:meta.latitude,lng:meta.longitude}:null;const taken=meta.DateTimeOriginal||meta.CreateDate;let takenAt=taken instanceof Date&&!isNaN(taken)?taken.toISOString():null;target.photos.push({id:crypto.randomUUID(),src,caption:file.name,gps:gps||targetStop?.gps||null,place:!gps&&targetStop?targetStop.name:'',takenAt,source:gps?'gps':targetStop?'manual':'unlocated'});added++;}catch{rejected++;}}busy=false;persist();if(!target.cover)target.cover=target.photos[0]?.id;if(!editingDraft)render();if(editingDraft){if(createStep===2)composerPlaces();else renderCreatePhotos()}else organize(false);toast(`${count(added,'photo')} added${rejected?' · '+rejected+' could not be read':''}. ${target.photos.filter(p=>!validGPS(p.gps)).length?'Place photos without location tags.':'Locations are grouped into stops.'}`);}
function openLocation(id){const j=activeJourney(),p=j.photos.find(p=>p.id===id);if(!p)return;locationState={id,isDraft:editingDraft,point:p.gps?{...p.gps}:null,name:p.place||''};const groups=getStops(j);modal('Add a photo location',`<span class="eyebrow">GIVE THIS MEMORY A PLACE</span><h2>Where was <em>this?</em></h2><div class="location-target"><img src="${esc(p.src)}" alt="Photo to locate"><div><strong>${p.gps?'Fine-tune this location':'No location tag found'}</strong><small>Choose a stop, tap the map, or enter coordinates.</small></div></div><div class="location-choices">${groups.map(s=>`<button data-action="choose-place" data-id="${esc(s.id)}">${esc(s.name)}</button>`).join('')}</div><div class="location-picker"><div id="picker-map" class="picker-map"></div><span class="picker-hint glass">${icon('pin')} Tap anywhere to place the photo</span></div><div class="coordinate-label" id="coordinate-label">${p.gps?`${p.gps.lat.toFixed(5)}, ${p.gps.lng.toFixed(5)}`:'No point selected yet'}</div><form id="location-form"><div class="field"><label for="location-name">Place name</label><input id="location-name" placeholder="A café, a beach, a little discovery…" maxlength="80" value="${esc(p.place||'')}"></div><details><summary class="small-action">Enter coordinates manually</summary><div class="field-grid"><div class="field"><label for="location-lat">Latitude</label><input id="location-lat" type="number" min="-90" max="90" step="any" value="${p.gps?.lat??''}"></div><div class="field"><label for="location-lng">Longitude</label><input id="location-lng" type="number" min="-180" max="180" step="any" value="${p.gps?.lng??''}"></div></div></details></form><p class="location-info" id="location-match">${p.gps?'You can move this photo to a different stop.':'A nearby photo joins an existing stop. A new place starts a new stop.'}</p>`,`<button class="small-action" data-action="${editingDraft?'organize-draft':'organize'}">← Back</button><button class="button dark" type="submit" form="location-form">Save location ${icon('pin')}</button>`);
 if(window.L){locationMap=L.map('picker-map',{zoomControl:true,scrollWheelZoom:false}).setView(p.gps?[p.gps.lat,p.gps.lng]:[40.631,14.52],p.gps?14:11);tileLayer(locationMap);groups.forEach(s=>L.circleMarker([s.gps.lat,s.gps.lng],{radius:6,color:'#3056e8',weight:2,fillColor:'#fff',fillOpacity:1}).addTo(locationMap).bindTooltip(esc(s.name)).on('click',()=>chooseLocation(s.gps,s.name)));locationMap.on('click',e=>chooseLocation({lat:e.latlng.lat,lng:e.latlng.lng},$('#location-name').value));if(p.gps)locationMarker=L.circleMarker([p.gps.lat,p.gps.lng],{radius:10,color:'#3056e8',weight:3,fillColor:'#fff',fillOpacity:.85}).addTo(locationMap);else locationMarker=null;locationMap.whenReady(()=>locationMap.invalidateSize());}
 const coordinateChange=()=>{const lat=$('#location-lat').value,lng=$('#location-lng').value;const point={lat:Number(lat),lng:Number(lng)};if(lat!==''&&lng!==''&&validGPS(point))chooseLocation(point,$('#location-name').value,false);else locationState.point=null;};$('#location-lat').oninput=coordinateChange;$('#location-lng').oninput=coordinateChange;
 $('#location-form').onsubmit=e=>{e.preventDefault();if(!validGPS(locationState.point)){toast('Choose a point on the map or enter valid coordinates.');return}const name=$('#location-name').value.trim();const nearest=groups.find(s=>distanceMeters(s.gps,locationState.point)<=j.radius);if(!name&&!nearest){toast('Give this new place a name.');$('#location-name').focus();return}const oldGroup=groups.find(g=>g.photos.some(photo=>photo.id===p.id));if(j.annotations[p.id]&&oldGroup?.photos.length>1&&distanceMeters(oldGroup.gps,locationState.point)>j.radius){const keeper=oldGroup.photos.find(photo=>photo.id!==p.id);const record=j.annotations[p.id];const other=j.annotations[keeper.id];j.annotations[keeper.id]={name:other?.name||record.name,notes:[...new Set([...(other?.notes||[]),...(record.notes||[])])],highlight:other?.highlight||record.highlight};delete j.annotations[p.id];}p.gps={...locationState.point};p.place=name||nearest.name;p.source='manual';const anchorAnnotation=j.annotations[p.id];if(anchorAnnotation&&name)anchorAnnotation.name=name;else if(!nearest&&name)j.annotations[p.id]={name,notes:[],highlight:''};locationState=null;persist();if(editingDraft)composerPlaces();else{render();organize(false)}toast(nearest?'Photo added to '+nearest.name:'A new stop has been added');};
}
function chooseLocation(point,name,writeCoordinates=true){locationState.point={...point};if(name)$('#location-name').value=name;if(writeCoordinates){$('#location-lat').value=point.lat.toFixed(6);$('#location-lng').value=point.lng.toFixed(6)}$('#coordinate-label').textContent=`${point.lat.toFixed(5)}, ${point.lng.toFixed(5)}`;const nearest=getStops(activeJourney()).find(s=>distanceMeters(s.gps,point)<=activeJourney().radius);$('#location-match').textContent=nearest?`This photo will join ${nearest.name}, with ${count(nearest.photos.length,'photo')}.`:'This photo will create a new stop on your journey.';if(locationMap){if(locationMarker)locationMarker.setLatLng([point.lat,point.lng]);else locationMarker=L.circleMarker([point.lat,point.lng],{radius:10,color:'#3056e8',weight:3,fillColor:'#fff',fillOpacity:.85}).addTo(locationMap);locationMap.panTo([point.lat,point.lng]);}}
function stepper(){const labels=['Photos','Places','Caption'];return `<div class="creation-progress"><div class="creation-progress-copy"><strong>Step ${createStep} of 3 · ${labels[createStep-1]}</strong><span>${createStep===3?'Ready to review':`${3-createStep} ${3-createStep===2?'steps':'step'} left`}</span></div><ol>${labels.map((label,i)=>`<li class="${i+1===createStep?'current':i+1<createStep?'complete':''}" ${i+1===createStep?'aria-current="step"':''}><span>${i+1<createStep?icon('check'):String(i+1).padStart(2,'0')}</span>${label}</li>`).join('')}</ol></div>`;}
function startCreate(){editingDraft=true;if(!draft){createStep=1;draft={id:crypto.randomUUID(),title:'',place:'',start:'',end:'',caption:'',cover:null,photos:[],annotations:{},radius:150,audience:'private',category:'Coast'};}if(createStep===2&&draft.photos.length)composerPlaces();else if(createStep>=3&&draft.photos.length)createStory();else renderCreatePhotos();}
function renderCreatePhotos(){editingDraft=true;createStep=1;screen='create';document.body.dataset.screen='create';renderShell('create');if($('#editor').open)$('#editor').close();pageMain(`${stepper()}<header class="creation-heading"><h1>Choose your photos</h1></header><section class="creation-surface"><div class="studio-panel-heading"><h2>Photos</h2><span>${String(draft.photos.length).padStart(2,'0')} / 40</span></div>${createPhotoBody()}</section><footer class="creation-footer"><button class="text-button delete-draft-link" data-action="delete-draft">Delete draft</button><button class="button primary" data-action="create-next" ${draft.photos.length?'':'disabled'}>Continue to places ${icon('arrow')}</button></footer>`,'workspace creation-page');bindUpload();persist();}

function createStory(){createStudio();}

function journeyName(caption,place){return place.trim()||caption.split(/[.!?\n]/)[0].trim().slice(0,72)||'A journey to remember';}
function collectStory(){if(!$('#story-form')||!draft)return;draft.place=$('#journey-place').value.trim();draft.start=$('#journey-start').value;draft.end=$('#journey-end').value;draft.caption=$('#journey-caption').value.trim();draft.title=journeyName(draft.caption,draft.place);draft.category=$('#journey-category').value;draft.audience=$('#journey-audience').value;}
function createPreview(){createStory();}
function nextCreate(){if(createStep===1){if(!draft.photos.length)return;draft.cover||=draft.photos[0].id;const known=draft.photos.map(p=>p.takenAt).filter(Boolean).sort();if(known.length){draft.start||=known[0].slice(0,10);draft.end||=known.at(-1).slice(0,10)}draft.place||=getStops(draft).map(s=>s.name).filter(Boolean).slice(0,2).join(', ');composerPlaces()}else{collectStory();createStory()}persist();window.scrollTo(0,0);}
function showCollection(onlySaved=false){go(onlySaved?'saved':'profile');}
function showGallery(){modal('Journey photo album',`<span class="eyebrow">EVERY MOMENT, KEPT</span><h2>Photos</h2><p class="modal-description">${count(journey.photos.length,'photo')} from ${esc(journey.place)}.</p><div class="full-gallery">${journey.photos.map(p=>{const s=stops.find(s=>s.photos.some(sp=>sp.id===p.id));return `<button data-action="photo" data-id="${esc(p.id)}"><img src="${esc(p.src)}" alt="${esc(p.caption||'Journey photo')}"><span>${s?esc(s.name):'＋ Add location'}</span></button>`}).join('')}</div>`,`${ownJourney()?'<button class="button" data-action="organize">Organize photos</button>':''}`);$('#editor').classList.add('gallery-sheet');}
function openPhoto(id){const group=stops.find(s=>s.photos.some(p=>p.id===id));lightboxIds=(group?group.photos:journey.photos).map(p=>p.id);lightboxIndex=lightboxIds.indexOf(id);renderLightbox();}
function renderLightbox(){const p=journey.photos.find(p=>p.id===lightboxIds[lightboxIndex]);if(!p)return;const s=stops.find(s=>s.photos.some(sp=>sp.id===p.id)),d=$('#lightbox');d.innerHTML=`<div class="lightbox-header"><span>${s?esc(s.name):'A memory waiting for a place'} · ${lightboxIndex+1} / ${lightboxIds.length}</span><button class="close" data-action="close-lightbox" aria-label="Close photo">×</button></div><img src="${esc(p.src)}" alt="${esc(p.caption||'Journey photo')}"><div class="lightbox-footer"><button data-action="photo-prev" ${lightboxIndex===0?'disabled':''}>${icon('back')}Previous</button>${ownJourney()?`<button data-action="photo-location" data-id="${esc(p.id)}">${icon('pin')}${p.gps?'Edit location':'Add location'}</button>`:''}<button data-action="photo-next" ${lightboxIndex===lightboxIds.length-1?'disabled':''}>Next ${icon('arrow')}</button></div>`;if(!d.open)d.showModal();}
function share(){const c=coverPhoto(journey);modal('Share journey',`<span class="eyebrow">SEND A LITTLE INSPIRATION</span><h2>Better <em>together.</em></h2><div class="collection-card"><img src="${esc(c.src)}" alt="${esc(journey.place)}"><div><h3>${esc(journey.place||'Journey')}</h3><p>${count(stops.length,'stop')} · ${count(journey.photos.length,'photo')}</p></div></div><p class="modal-description">Copy a link to this journey in your local preview.</p><p class="helper">This link needs the local app running. Your own journeys are stored in this browser, so they aren’t available to other people yet.</p>`,`<span class="muted">Local preview link</span><button class="button dark" data-action="copy-link">Copy link ${icon('share')}</button>`);}
function changeView(next){view=next;render();$('.journey-canvas').scrollIntoView({block:'center',behavior:'smooth'});}

function closeEditor(){if(editingDraft&&$('#story-form'))collectStory();persist();$('#editor').close();if(locationMap){locationMap.remove();locationMap=null}locationState=null;editingDraft=screen==='create';}
function allJourneys(){return [...journeys,sampleState,...communityJourneys];}
function findJourney(id){return allJourneys().find(j=>j.id===id);}
function ownJourney(j=journey){return !j.author||j.author==='me';}
function person(id='me'){return id==='me'?profile:people[id]||profile;}
function dayCount(j){return Math.max(1,Math.round((Date.parse(j.end)-Date.parse(j.start))/86400000)+1)||1;}
function avatar(p,extra=''){return `<span class="person-avatar ${p.color||'sage'} ${extra}" aria-hidden="true">${esc(p.initials||p.name.slice(0,2))}</span>`;}
function snapshot(){return {version:1,journeys,sampleState,draft,createStep,profile,savedIds:[...savedIds],likedIds:[...likedIds],following:[...following],comments,storyIds};}
function persist(){clearTimeout(saveTimer);saveTimer=setTimeout(flushState,180);}
async function flushState(){clearTimeout(saveTimer);try{await writeState(snapshot());$$('.autosave-label').forEach(e=>e.textContent='Saved on this device');return true;}catch{if(!storageWarned){storageWarned=true;toast('Device storage is unavailable. Keep this tab open to retain your changes.');}return false;}}
function routeFromHash(){const [page,id]=location.hash.replace(/^#\/?/,'').split('/');return {page:['home','explore','saved','profile','journey','create','connections','editprofile'].includes(page)?page:'home',id:id?decodeURIComponent(id):null};}
function go(page,id){if(editingDraft&&$('#story-form'))collectStory();persist();closeEditor();$('#stop-sheet').close();$('#lightbox').close();if(screen!=='journey'&&page==='journey')returnScreen=screen;history.pushState({atlasPrevious:location.hash},'',`#/${page}${id?'/'+encodeURIComponent(id):''}`);renderScreen();$('#journey').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function renderScreen(){clearExploreMap();const r=routeFromHash();screen=r.page;document.body.dataset.screen=screen;renderShell(screen);if(screen==='journey'){const j=findJourney(r.id);if(!j){go('home');toast('This journey is not available on this device.');return}journey=structuredClone(j);render();}else if(screen==='home')renderHome();else if(screen==='explore')renderExplore();else if(screen==='saved')renderSaved();else if(screen==='profile')renderProfile(r.id||'me');else if(screen==='connections')renderConnections(r.id||'me');else if(screen==='editprofile')renderEditProfile();else startCreate();}
function renderShell(active){
 const legacy=active==='journey';document.querySelectorAll('[data-legacy-style]').forEach(l=>l.media=legacy?'all':'not all');$('#experience-style').media=legacy?'not all':'all';$('.app-sidebar')?.remove();
 if(legacy){renderLegacyShell(active);return;}
 const contextual=['create','connections','editprofile'].includes(active);const tabs=[['home','Feed'],['explore','Explore'],['saved','Saved'],['profile','You']];const mobileTitle={explore:'Explore',saved:'Saved',profile:'Profile'}[active]||'';
 $('.site-nav').innerHTML=contextual?`<div class="context-header"><button class="context-back" data-action="${active==='create'?'save-draft':'toolbar-back'}" aria-label="Back">${icon('back')}</button><span>${active==='create'?'New travel post':active==='editprofile'?'Edit profile':'Connections'}</span></div><div class="header-tools">${active==='create'?'<button class="button secondary" data-action="save-draft">Save draft</button>':''}</div>`:`<a class="atlas-wordmark" href="#/home" aria-label="Atlas feed"><span class="atlas-emblem">${icon('route')}</span>atlas</a><span class="mobile-section-title">${mobileTitle}</span><nav class="top-navigation" aria-label="Main navigation">${tabs.map(([id,label])=>`<button data-action="nav" data-id="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="header-tools"><button class="button primary" data-action="create">${icon('plus')}New post</button></div>`;
 $('.mobile-dock').innerHTML='<div class="dock-lens">'+[['home','story','Feed'],['explore','compass','Explore'],['saved','save','Saved'],['profile','person','You']].map(([id,ic,label])=>`<button data-action="nav" data-id="${id}" class="${active===id?'active':''}" aria-label="${label}" ${active===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')+'</div>'+`<button class="dock-compose" data-action="create" aria-label="Create a post">${icon('plus')}</button>`;$('.mobile-dock').hidden=contextual;
}

function renderLegacyShell(active){
 const tabs=[['home','home','Home'],['explore','compass','Explore'],['profile','person','You']];
 const route=routeFromHash(), otherProfile=active==='profile'&&route.id&&route.id!=='me';
 const root=['home','explore','profile'].includes(active)&&!otherProfile;
 const title=({home:'Home',explore:'Explore',profile:otherProfile?'Traveler':'Your journal',saved:'Saved journeys',connections:'Connections',editprofile:'Edit profile',journey:journey.place||'Journey',create:createStep===1?'New journey':createStep===2?'Places & notes':'Your story'})[active];
 const back=root?'':`<button class="toolbar-icon" data-action="${active==='create'?(createStep===1?'save-draft':'create-back'):'toolbar-back'}" aria-label="${active==='create'&&createStep===1?'Save and close':'Back'}">${icon(active==='create'&&createStep===1?'close':'back')}</button>`;
 let actions='';
 if(active==='home'||active==='explore')actions=`<button class="toolbar-icon" data-action="nav" data-id="saved" aria-label="Saved journeys">${icon('save')}</button>`;
 if(active==='profile'&&!otherProfile)actions=`<button class="toolbar-icon" data-action="settings" aria-label="Settings">${icon('settings')}</button>`;
 if(active==='journey')actions=`<button class="toolbar-icon" data-action="save" aria-label="${savedIds.has(journey.id)?'Unsave':'Save'} journey" aria-pressed="${savedIds.has(journey.id)}">${icon('save')}</button><button class="toolbar-icon" data-action="share" aria-label="Preview journey link">${icon('share')}</button>`;
 if(active==='create')actions='<button class="toolbar-text" data-action="save-draft">Save & close</button>';
 if(active==='editprofile')actions='<button class="toolbar-text" type="submit" form="profile-form">Save</button>';
 const subtitle=active==='create'?(createStep===2?'OPTIONAL DETAILS':`STEP ${createStep===1?1:2} OF 2`):'';
 const heading=active==='home'?'<div class="home-wordmark" aria-label="Atlas home"><span class="home-mark" aria-hidden="true"><i></i></span><span>atlas<span class="home-wordmark-dot">.</span></span></div>':`<div class="toolbar-heading">${subtitle?`<span class="toolbar-kicker">${subtitle}</span>`:''}<span class="toolbar-title">${esc(title)}</span></div>`;
 $('.site-nav').innerHTML=`<div class="toolbar-leading">${back}${heading}</div>${root?`<nav class="desktop-nav" aria-label="Main navigation">${tabs.map(([id,ic,label])=>`<button data-action="nav" data-id="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`:''}<div class="toolbar-actions">${root?`<button class="button dark nav-create" data-action="create">${icon('plus')}New journey</button>`:''}${actions}</div>`;
 $('.mobile-dock').setAttribute('aria-label','Main navigation');
 $('.mobile-dock').innerHTML=`<div class="dock-island">${tabs.map(([id,ic,label])=>`<button data-action="nav" data-id="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}</div><button class="dock-create" data-action="create" aria-label="Create a new journey">${icon('plus')}</button>`;
 $('.mobile-dock').hidden=!root;
}

function pageMain(html,cls='app-page'){$('#journey').className=cls;$('#journey').innerHTML=html;}
function categoryChips(action,current){return `<div class="explore-categories" role="group" aria-label="Journey categories">${['All','Coast','Mountains','City'].map(c=>`<button data-action="${action}" data-id="${c}" class="${current===c?'active':''}" aria-pressed="${current===c}">${c}</button>`).join('')}</div>`;}

function routeRibbon(j){const ss=getStops(j),chosen=ss.length>3?[ss[0],ss[Math.floor(ss.length/2)],ss.at(-1)]:ss;return `<div class="route-ribbon" aria-label="Journey stops"><div class="ribbon-line"></div>${chosen.map((s,i)=>`<span><i class="${i===chosen.length-1?'last':''}"></i><small>${esc(s.name)}</small></span>`).join('')}${!ss.length?'<small>Memories waiting for a place</small>':''}</div>`;}
function journeyCard(j,compact=false){const ss=getStops(j);return `<article class="journal-entry"><div class="entry-date"><strong>${j.start?date(j.start,{month:'short'}):'NEW'}</strong><span>${j.start?date(j.start,{year:'numeric'}):'JOURNEY'}</span></div><button class="entry-photo" data-action="open-journey" data-id="${esc(j.id)}" aria-label="Open ${esc(j.place||'Journey')}"><img src="${esc(coverPhoto(j)?.src||media.positano)}" alt="${esc(j.place)}" loading="lazy"></button><div class="entry-copy"><span class="overline">${count(ss.length,'stop')} · ${count(j.photos.length,'photo')}${j.demo?' · EXAMPLE':''}</span><button class="entry-title" data-action="open-journey" data-id="${esc(j.id)}"><h2>${esc(j.place||'Journey')}</h2></button><p>${esc(j.caption||`${dayCount(j)} days on the road`)}</p><div class="entry-stops">${ss.slice(0,3).map(v=>`<span>${esc(v.name)}</span>`).join('<i></i>')}</div></div><button class="entry-open" data-action="open-journey" data-id="${esc(j.id)}" aria-label="Open ${esc(j.place||'Journey')}">${icon('diagonal')}</button></article>`;}

function draftNudge(){return `<button class="draft-resume" data-action="create"><span class="draft-thumb">${draft?.photos.length?`<img src="${esc(coverPhoto(draft).src)}" alt="">`:icon('edit')}</span><span><span class="overline">IN PROGRESS</span><strong>${esc(draft?.place||'Unfinished post')}</strong><small>${count(draft?.photos.length||0,'photo')} · Continue where you left off</small></span><span class="draft-continue">Continue ${icon('edit')}</span></button>`;}

function feedRoute(j){const ss=getStops(j),selected=feedExpandedStop?.journeyId===j.id?ss.find(s=>s.id===feedExpandedStop.stopId):null;return `<section class="feed-journey" aria-label="${esc(j.place||'Journey')} route"><div class="feed-journey-heading"><span>${icon('route')}${count(ss.length,'stop')} on this journey</span><button data-action="open-journey" data-id="${esc(j.id)}">Full story ${icon('arrow')}</button></div>${ss.length?`<div class="feed-journey-track ${ss.length<=4?'few-stops':'many-stops'}" style="--stop-count:${ss.length}">${ss.map((s,i)=>`<button class="feed-journey-stop ${selected?.id===s.id?'active':''}" data-action="feed-stop" data-id="${esc(j.id)}" data-stop="${esc(s.id)}" aria-expanded="${selected?.id===s.id}"><span class="feed-stop-image"><img src="${esc(s.photos[0]?.src||coverPhoto(j).src)}" alt=""><small>${String(i+1).padStart(2,'0')}</small></span><strong>${esc(s.name)}</strong></button>`).join('')}</div>`:'<p class="feed-route-empty">Photos are waiting for a place.</p>'}${selected?`<div class="feed-stop-note"><img src="${esc(selected.photos[0]?.src||coverPhoto(j).src)}" alt="${esc(selected.name)}"><div><strong>${esc(selected.name)}</strong><p>${esc(selected.notes[0]||selected.highlight||'A moment from this stop.')}</p></div><button data-action="feed-stop" data-id="${esc(j.id)}" data-stop="${esc(selected.id)}" aria-label="Close stop preview">${icon('close')}</button></div>`:''}</section>`;}
function feedPhotoSpread(j){
 const cover=coverPhoto(j),stops=getStops(j),coverStop=stops.find(s=>s.photos.some(p=>p.id===cover.id));
 const items=[{photo:cover,name:coverStop?.name||j.place,stopId:coverStop?.id||null}];
 const otherStops=stops.filter(s=>s.id!==coverStop?.id),slots=Math.min(4,otherStops.length);
 for(let i=0;i<slots;i++){const s=otherStops[Math.round(i*(otherStops.length-1)/Math.max(1,slots-1))];items.push({photo:s.photos[0],name:s.name,stopId:s.id})}
 for(const photo of j.photos){if(items.length>=5)break;if(!items.some(item=>item.photo.id===photo.id))items.push({photo,name:photo.place||j.place,stopId:stops.find(s=>s.photos.some(p=>p.id===photo.id))?.id||null})}
 const visible=items.slice(0,5);
 return `<div class="feed-photo-story ${visible.length>1?'multi':''} photo-count-${visible.length}" aria-label="Photos from ${esc(j.place||'Journey')}">${visible.map((item,i)=>`<button class="feed-photo-tile ${i===0?'featured':''}" data-action="${item.stopId?'feed-stop':'open-journey'}" data-id="${esc(j.id)}" ${item.stopId?`data-stop="${esc(item.stopId)}"`:''} aria-label="${item.stopId?'Preview':'Open'} ${esc(item.name)} in ${esc(j.place||'Journey')}"><img src="${esc(item.photo.src)}" alt="${esc(item.photo.caption||item.name)}" loading="lazy"><span class="feed-photo-label">${esc(item.name)}</span></button>`).join('')}<span class="feed-photo-total">${icon('photos')}${count(j.photos.length,'photo')}</span></div>`;
}
function feedPost(j){const p=person(j.author);return `<article class="social-post" aria-label="${esc(j.place||'Journey')}"><header class="social-post-header"><button class="post-person" data-action="author" data-id="${p.id}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(j.place)}${j.demo?' · Sample journey':''}</small></span></button><span class="post-date">${j.start?date(j.start):'New'}</span></header>${feedPhotoSpread(j)}${feedRoute(j)}<div class="social-post-actions"><div>${socialActions(j)}<button class="post-action" data-action="share-post" data-id="${esc(j.id)}" aria-label="Preview sharing ${esc(j.place||'Journey')}">${icon('share')}</button></div><button class="post-save ${savedIds.has(j.id)?'saved':''}" data-action="toggle-save" data-id="${esc(j.id)}" aria-label="${savedIds.has(j.id)?'Unsave':'Save'} ${esc(j.place||'Journey')}" aria-pressed="${savedIds.has(j.id)}">${icon('save')}</button></div>${j.caption?`<div class="social-post-copy"><p class="feed-caption">${esc(j.caption)}</p></div>`:''}</article>`;}
function renderHome(){
 const list=allJourneys().filter(j=>(feedTab==='all'||following.has(j.author))&&(feedCategory==='All'||j.category===feedCategory));
 pageMain(`<div class="social-layout"><section class="social-main"><div class="feed-story-rail"><button class="feed-story-own" data-action="add-story"><span>${icon('plus')}</span><strong>Your story</strong></button>${storyIds.map(id=>findJourney(id)).filter(Boolean).map(j=>`<button class="feed-story" data-action="story" data-id="${j.id}"><span><img src="${esc(coverPhoto(j).src)}" alt=""></span><strong>${esc(person(j.author).name.split(' ')[0])}</strong></button>`).join('')}</div><div class="feed-filter-bar"><div role="group" aria-label="Feed"><button data-action="feed-tab" data-id="all" class="${feedTab==='all'?'active':''}" aria-pressed="${feedTab==='all'}">For you</button><button data-action="feed-tab" data-id="following" class="${feedTab==='following'?'active':''}" aria-pressed="${feedTab==='following'}">Following</button></div><span>${count(list.length,'journey')}</span></div>${draft?.photos.length?draftNudge():''}<div class="social-feed">${list.map(j=>feedPost(j)).join('')||emptyState('A quiet moment.','Follow a traveler or choose another category to fill your feed.','Explore','explore')}</div></section><aside class="social-rail"><div class="social-rail-sticky"><div class="rail-profile">${avatar(profile)}<span><strong>${esc(profile.name)}</strong><small>@${esc(profile.handle)}</small></span><button data-action="nav" data-id="profile">View</button></div><div class="rail-section"><span class="overline">EXPLORE BY MOOD</span>${['All','Coast','Mountains','City'].map(c=>`<button class="rail-category ${feedCategory===c?'active':''}" data-action="feed-category" data-id="${c}"><span>${icon(c==='Coast'?'sun':c==='Mountains'?'mountain':c==='City'?'city':'compass')}${c==='All'?'All journeys':c}</span>${icon('diagonal')}</button>`).join('')}</div><div class="rail-section"><span class="overline">PEOPLE TO FOLLOW</span>${Object.values(people).filter(p=>p.id!=='me').map(p=>`<div class="rail-traveler"><button data-action="author" data-id="${p.id}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.location)}</small></span></button><button class="rail-follow" data-action="follow" data-id="${p.id}" aria-label="${following.has(p.id)?'Unfollow':'Follow'} ${esc(p.name)}">${following.has(p.id)?icon('check'):icon('plus')}</button></div>`).join('')}</div><button class="rail-saved" data-action="nav" data-id="saved">${icon('save')}Your saved journeys <span>${savedIds.size}</span></button><p class="rail-footnote">Sample community · Your posts stay on this device.</p></div></aside></div>`,'workspace feed-page');
}

function emptyState(title,body,label,page){return `<div class="empty-journal"><span class="empty-symbol">${icon('route')}</span><h2>${title}</h2><p>${body}</p><button class="button secondary" data-action="nav" data-id="${page}">${label}</button></div>`;}

let exploreMap=null,exploreMarkerLayer=null,exploreRouteLayer=null,exploreOverviewPositions=[],exploreMarkerById=new Map();
function clearExploreMap(){if(exploreMap){exploreMap.remove();exploreMap=null;exploreMarkerLayer=null;exploreRouteLayer=null;exploreOverviewPositions=[];exploreMarkerById.clear()}}
function renderExplore(){
 clearExploreMap();
 pageMain(`<div class="explore-workspace"><header class="explore-top"><label class="explore-search">${icon('search')}<input id="explore-search" type="search" placeholder="Search a place, stop, or moment" aria-label="Search journeys" value="${esc(searchQuery)}"></label></header><div class="explore-filters"><div class="explore-source" role="group" aria-label="Journey source"><button data-action="discovery-audience" data-id="all" class="${feedTab==='all'?'active':''}" aria-pressed="${feedTab==='all'}">Everyone</button><button data-action="discovery-audience" data-id="following" class="${feedTab==='following'?'active':''}" aria-pressed="${feedTab==='following'}">Following</button></div>${categoryChips('explore-category',exploreCategory)}</div><div class="explore-content"><section class="explore-map-panel" aria-label="Journey map"><div class="explore-section-heading"><h2>On the map</h2><span id="explore-result-count" role="status"></span></div><div class="explore-map-wrap"><div id="explore-map" aria-label="Map of journey destinations"></div><div id="explore-map-selection" class="explore-map-selection" hidden></div></div><p class="explore-map-hint">Select a photo pin to trace its stops.</p></section><section class="explore-destinations"><div class="explore-section-heading"><h2>Places to explore</h2></div><div id="explore-results" class="explore-card-grid"></div></section></div></div>`,'workspace discover-page');
 if(window.L){exploreMap=L.map('explore-map',{zoomControl:false,scrollWheelZoom:false,attributionControl:true});tileLayer(exploreMap);exploreMarkerLayer=L.layerGroup().addTo(exploreMap);exploreRouteLayer=L.layerGroup().addTo(exploreMap);exploreMap.setView([37,35],3);exploreMap.whenReady(()=>exploreMap.invalidateSize());}
 renderSearchResults();$('#explore-search').oninput=e=>{searchQuery=e.target.value;renderSearchResults()};
}
function renderSearchResults(){
 const q=searchQuery.trim().toLowerCase();
 const list=allJourneys().filter(j=>(feedTab!=='following'||following.has(j.author))&&(exploreCategory==='All'||j.category===exploreCategory)&&`${j.place} ${j.category} ${j.caption} ${person(j.author).name} ${getStops(j).map(s=>s.name+' '+s.notes.join(' ')).join(' ')}`.toLowerCase().includes(q));
 explorerSelection=null;exploreRouteLayer?.clearLayers();const selectedPanel=$('#explore-map-selection');if(selectedPanel)selectedPanel.hidden=true;const status=$('#explore-result-count');if(status)status.textContent=count(list.length,'journey');
 $('#explore-results').innerHTML=list.map(j=>{const ss=getStops(j),author=person(j.author);return `<article class="explore-destination ${explorerSelection===j.id?'selected':''}" data-explore-id="${esc(j.id)}"><button class="explore-destination-photo" data-action="open-journey" data-id="${esc(j.id)}" aria-label="Open journey through ${esc(j.place)}"><img src="${esc(coverPhoto(j).src)}" alt="${esc(j.place)}" loading="lazy"><span>${esc(j.place)}</span></button><div class="explore-destination-body"><div class="explore-destination-meta">${avatar(author)}<span>${esc(author.name)}</span><i></i><span>${count(ss.length,'stop')} · ${dayCount(j)} days</span><button class="${savedIds.has(j.id)?'saved':''}" data-action="toggle-save" data-id="${esc(j.id)}" aria-label="${savedIds.has(j.id)?'Unsave':'Save'} ${esc(j.place)}">${icon('save')}</button></div>${j.caption?`<p class="explore-destination-caption">${esc(j.caption)}</p>`:''}<div class="explore-destination-stops" aria-label="Stops in ${esc(j.place)}">${ss.slice(0,4).map(s=>`<span>${esc(s.name)}</span>`).join('')}${ss.length>4?`<span>+${ss.length-4}</span>`:''}</div><div class="explore-destination-actions"><button data-action="explore-focus" data-id="${esc(j.id)}">Show route ${icon('route')}</button><button data-action="open-journey" data-id="${esc(j.id)}">View journey ${icon('arrow')}</button></div></div></article>`}).join('')||`<div class="explore-empty"><strong>No places found</strong><p>Try another search or category.</p><button class="text-button" data-action="clear-explore">Clear filters ${icon('arrow')}</button></div>`;
 if(!exploreMap||!exploreMarkerLayer)return;
 exploreMarkerLayer.clearLayers();exploreMarkerById.clear();const positions=[];
 list.forEach(j=>{const stop=getStops(j).find(s=>validGPS(s.gps));if(!stop)return;const coords=[stop.gps.lat,stop.gps.lng];positions.push(coords);const marker=L.marker(coords,{icon:L.divIcon({className:'explore-map-marker',html:`<img src="${esc(coverPhoto(j).src)}" alt=""><span>${esc(j.place.split(',')[0])}</span>`,iconSize:[42,54],iconAnchor:[21,21]}),title:j.place});marker.on('click',()=>focusExplore(j.id,false));marker.addTo(exploreMarkerLayer);exploreMarkerById.set(j.id,marker)});
 exploreOverviewPositions=positions;if(positions.length>1)exploreMap.fitBounds(positions,{padding:[52,52],maxZoom:8});else if(positions.length)exploreMap.setView(positions[0],8);else exploreMap.setView([37,35],3);
}
function focusExplore(id,showMap=true){
 const j=findJourney(id);if(!j||!exploreMap)return;explorerSelection=id;
 document.querySelectorAll('.explore-destination').forEach(card=>card.classList.toggle('selected',card.dataset.exploreId===id));
 exploreRouteLayer.clearLayers();const ss=getStops(j).filter(s=>validGPS(s.gps)),coords=ss.map(s=>[s.gps.lat,s.gps.lng]);
 if(coords.length>1){L.polyline(coords,{color:'#fff',weight:7,opacity:.9}).addTo(exploreRouteLayer);L.polyline(coords,{color:'#416a78',weight:3,opacity:1}).addTo(exploreRouteLayer)}
 ss.forEach((stop,i)=>L.circleMarker(coords[i],{radius:i===0||i===ss.length-1?7:5,color:'#fff',weight:2,fillColor:'#416a78',fillOpacity:1}).bindTooltip(`${i+1}. ${stop.name}`,{direction:'top'}).addTo(exploreRouteLayer));
 if(coords.length>1)exploreMap.fitBounds(coords,{paddingTopLeft:[42,42],paddingBottomRight:[42,145],maxZoom:12});else if(coords.length)exploreMap.setView(coords[0],12);
 const panel=$('#explore-map-selection');panel.hidden=false;panel.innerHTML=`<img src="${esc(coverPhoto(j).src)}" alt=""><span><strong>${esc(j.place)}</strong><small>${count(ss.length,'stop')} · ${dayCount(j)} days</small></span><button class="explore-map-open" data-action="open-journey" data-id="${esc(j.id)}" aria-label="Open journey through ${esc(j.place)}">${icon('arrow')}</button><button class="explore-map-reset" data-action="explore-reset" aria-label="Back to all places">${icon('close')}</button>`;
 if(showMap)document.querySelector('.explore-map-panel')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});
}
function resetExploreMap(){explorerSelection=null;exploreRouteLayer?.clearLayers();const panel=$('#explore-map-selection');if(panel)panel.hidden=true;document.querySelectorAll('.explore-destination').forEach(card=>card.classList.remove('selected'));if(!exploreMap)return;if(exploreOverviewPositions.length>1)exploreMap.fitBounds(exploreOverviewPositions,{padding:[52,52],maxZoom:8});else if(exploreOverviewPositions.length)exploreMap.setView(exploreOverviewPositions[0],8);else exploreMap.setView([37,35],3);}

function renderSaved(){const list=allJourneys().filter(j=>savedIds.has(j.id));pageMain(`<div class="saved-summary"><span>${count(list.length,'journey')}</span><button class="text-button" data-action="nav" data-id="explore">Explore places ${icon('compass')}</button></div><div class="book-shelf">${list.map((j,i)=>`<article class="journey-book"><button class="book-cover" data-action="open-journey" data-id="${esc(j.id)}"><img src="${esc(coverPhoto(j).src)}" alt="${esc(j.place)}"><span class="book-spine">ATLAS JOURNAL / ${String(i+1).padStart(2,'0')}</span><span class="book-title">${esc(j.place.split(',')[0])}<small>${esc(person(j.author).name)}</small></span></button><div class="book-caption"><span>${count(getStops(j).length,'stop')} · ${dayCount(j)} days</span><button data-action="toggle-save" data-id="${esc(j.id)}" aria-label="Remove ${esc(j.place||'Journey')} from saved">${icon('save')}Saved</button></div></article>`).join('')}<button class="empty-book" data-action="nav" data-id="explore">${icon('plus')}<strong>${list.length?'Leave room for more.':'Your first someday.'}</strong><span>Discover a journey.<br>Save what stays with you.</span></button></div>`,'workspace saved-page');}

function renderProfile(id='me'){const p=person(id),mine=id==='me',list=(mine?journeys:allJourneys()).filter(j=>(j.author||'me')===id),photos=list.flatMap(j=>j.photos),places=list.reduce((a,j)=>a+getStops(j).length,0);pageMain(`<div class="passport-layout"><aside class="passport"><span class="overline">${mine?'YOUR TRAVELER’S ID':'SAMPLE TRAVELER'}</span><div class="passport-identity">${avatar(p)}<h1>${esc(p.name)}</h1><span>@${esc(p.handle)}</span></div><div class="passport-home">${icon('pin')}<span><small>HOME BASE</small>${esc(p.location||'Somewhere in the world')}</span></div><p class="passport-bio">${esc(p.bio)}</p><div class="passport-statistics"><span><strong>${String(list.length).padStart(2,'0')}</strong>Journeys</span><span><strong>${String(places).padStart(2,'0')}</strong>Places</span><span><strong>${String(photos.length).padStart(2,'0')}</strong>Photos</span></div><div class="passport-connections"><button data-action="connections" data-id="${id}" data-tab="followers">${followerIds(id).length} followers</button><button data-action="connections" data-id="${id}" data-tab="following">${mine?following.size:1} following</button></div>${mine?`<button class="button secondary" data-action="edit-profile">${icon('edit')}Edit traveler’s ID</button><button class="text-button" data-action="settings">${icon('settings')}Settings & privacy</button>`:`<button class="button primary" data-action="follow" data-id="${id}">${following.has(id)?'Following':'+ Follow traveler'}</button>`}<span class="passport-footer">ATLAS / PERSONAL JOURNAL</span></aside><section class="passport-journal"><div class="profile-view-switch" role="group" aria-label="Profile sections">${['journeys','photos',...(mine?['drafts']:[])].map(t=>`<button data-action="profile-tab" data-id="${t}" data-person="${id}" class="${profileTab===t?'active':''}" aria-pressed="${profileTab===t}">${icon(t==='journeys'?'route':t==='photos'?'photos':'edit')}${t==='journeys'?'Journeys':t==='photos'?'Contact sheet':'Drafts'}</button>`).join('')}</div>${profileTab==='drafts'?draft?.photos.length?draftNudge():emptyState('Nothing left unfinished.','Start a journey and return to your draft whenever you like.','New journey','create'):profileTab==='photos'?`<div class="contact-sheet">${list.flatMap(j=>j.photos.map((v,i)=>`<button data-action="profile-photo" data-id="${v.id}" data-journey="${j.id}"><img src="${v.src}" alt="${esc(v.caption||j.place)}" loading="lazy"><span>${String(i+1).padStart(2,'0')} / ${esc(v.place||'A moment')}</span></button>`)).join('')||emptyState('Your moments will live here.','Photos from your saved journeys form your personal contact sheet.','Create a journey','create')}</div>`:list.length?`<div class="journal-timeline">${list.map(j=>journeyCard(j)).join('')}</div>`:emptyState('A world of stories ahead.','One photo is enough to start your journal.','Create a journey','create')}</section></div>`,'workspace profile-page');}

function editProfile(){go('editprofile');}
function socialSheetHeader(label,total){$('#editor .modal-header').innerHTML=`<div class="social-sheet-heading"><span class="social-sheet-grabber" aria-hidden="true"></span><h2>${label}<small>${total}</small></h2></div><button class="social-sheet-close" data-action="close-editor" aria-label="Close ${label.toLowerCase()}">${icon('close')}</button>`;}
function showComments(id){const j=findJourney(id);if(!j)return;modal('Comments',`<div class="comments-list">${commentItems(id)||'<p class="comment-empty">No comments yet. Start the conversation.</p>'}</div>`,`<form id="sheet-comment-form" class="sheet-comment-form" data-journey="${esc(id)}"><label class="sr-only" for="sheet-comment-text">Write a comment</label>${avatar(profile)}<textarea id="sheet-comment-text" maxlength="1000" rows="1" placeholder="Add a comment…" required></textarea><button class="button dark" type="submit" aria-label="Post comment">Post</button></form>`);$('#editor').classList.add('comments-sheet');socialSheetHeader('Comments',allComments(id).length);}

function showLikes(id){const j=findJourney(id);if(!j)return;const ids=[...(likedIds.has(id)?['me']:[]),...(demoSocial[id]?.likedBy||[])],remaining=Math.max(0,likesCount(id)-ids.length);modal('Likes',`<div class="likes-list">${ids.length?ids.map(personId=>{const p=person(personId);return `<button class="likes-person" data-action="author" data-id="${esc(personId)}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${personId==='me'?'You liked this journey':'Traveler'}</small></span></button>`}).join(''):'<p class="comment-empty">No likes yet.</p>'}</div>${remaining?`<p class="likes-aggregate">And ${count(remaining,'more sample like')}.</p>`:''}`);$('#editor').classList.add('likes-sheet');socialSheetHeader('Likes',likesCount(id));}

function showFollowing(){go('connections',routeFromHash().id||'me');}
function previewPost(){if(!draft?.photos.length){toast('Add at least one photo.');return}if((draft.start&&!draft.end)||(!draft.start&&draft.end)||(draft.start&&draft.end<draft.start)){toast('Choose a valid start and end date.');return}const p={...draft,author:'me'};modal('Review your post',`<div class="post-review"><span class="overline">THE FINAL LOOK</span><h2>Ready for your journal?</h2><div class="post-review-photo"><img src="${esc(coverPhoto(p).src)}" alt="${esc(p.place||'Journey')}"><span>${count(p.photos.length,'photo')}</span></div><div class="post-review-body"><span>${esc(p.place||'A journey')}</span>${p.caption?`<p>${esc(p.caption)}</p>`:'<p>Photos only, no caption.</p>'}</div><p class="post-review-note">${icon('lock')}Saved privately on this device. This preview does not publish online.</p></div>`,`<button class="text-button" data-action="close-editor">Keep editing</button><button class="button primary" data-action="post">Save post ${icon('check')}</button>`);}
function createStudio(){
 editingDraft=true;createStep=3;screen='create';document.body.dataset.screen='create';renderShell('create');if($('#editor').open)$('#editor').close();
 pageMain(`${stepper()}<header class="creation-heading"><h1>Write a caption</h1></header><div class="story-step-layout"><aside class="story-step-cover"><img src="${esc(coverPhoto(draft).src)}" alt="${esc(draft.place||'Your post cover')}"><span>${count(draft.photos.length,'photo')} · ${count(getStops(draft).length,'stop')}</span></aside><section class="creation-surface story-step-fields"><form id="story-form"><div class="field"><label for="journey-place">Destination</label><input id="journey-place" placeholder="Place or destination" maxlength="100" value="${esc(draft.place)}"></div><div class="field"><label for="journey-caption">Caption</label><textarea id="journey-caption" rows="4" maxlength="1200" placeholder="The little detour. The long lunch. The view you almost missed.">${esc(draft.caption)}</textarea></div><div class="field-grid"><div class="field"><label for="journey-start">First day</label><input id="journey-start" type="date" value="${esc(draft.start)}"></div><div class="field"><label for="journey-end">Last day</label><input id="journey-end" type="date" value="${esc(draft.end)}"></div></div><div class="field-grid"><div class="field"><label for="journey-category">Kind of trip</label><select id="journey-category">${['Coast','Mountains','City'].map(c=>`<option ${draft.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="journey-audience">Audience preview</label><select id="journey-audience">${['private','followers','everyone'].map(v=>`<option value="${v}" ${draft.audience===v?'selected':''}>${audienceName(v)}</option>`).join('')}</select></div></div><p class="studio-privacy">${icon('lock')}Saved on this device. Nothing is shared online.</p></form></section></div><footer class="creation-footer"><button class="text-button" data-action="create-back">${icon('back')} Places</button><button class="button primary" type="submit" form="story-form">Review post ${icon('arrow')}</button></footer><button class="text-button delete-draft-link" data-action="delete-draft">Delete draft</button>`,'workspace creation-page story-step-page');
 $('#story-form').oninput=()=>{collectStory();persist()};$('#story-form').onchange=()=>{collectStory();persist()};$('#story-form').onsubmit=e=>{e.preventDefault();collectStory();previewPost()};persist();
}
function composerLayout(title,subtitle,body,footer){screen='create';document.body.dataset.screen='create';renderShell('create');if($('#editor').open)$('#editor').close();pageMain(`${stepper()}<header class="creation-heading"><h1>Places & moments</h1></header><div class="places-workspace">${body}</div><footer class="places-footer"><button class="text-button" data-action="create-back">${icon('back')} Photos</button><button class="button primary" data-action="create-next">Continue to story ${icon('arrow')}</button></footer><button class="text-button delete-draft-link" data-action="delete-draft">Delete draft</button>`,'workspace places-page creation-page');persist();}

function createPhotoBody(){return `${uploadMarkup()}${draft.photos.length?`<div class="studio-photo-grid">${draft.photos.map((p,i)=>`<div class="studio-photo ${p.id===draft.cover?'cover':''}"><button class="studio-photo-cover" data-action="studio-cover" data-id="${esc(p.id)}" aria-label="Use ${esc(p.caption||'photo')} as cover" aria-pressed="${p.id===draft.cover}"><img src="${esc(p.src)}" alt="${esc(p.caption||'Selected photo')}"><span>${p.id===draft.cover?'COVER':String(i+1).padStart(2,'0')}</span></button><button class="studio-remove" data-action="remove-draft-photo" data-id="${esc(p.id)}" aria-label="Remove ${esc(p.caption||'photo')}">${icon('close')}</button></div>`).join('')}</div>`:''}<button class="text-button sample-photos-button" data-action="use-demo">${icon('photos')}Try the studio with sample photos</button>`;}

function composerPlaces(){editingDraft=true;createStep=2;const groups=getStops(draft),unplaced=draft.photos.filter(p=>!validGPS(p.gps));composerLayout('','',`${unplaced.length?`<section class="unplaced-section glass"><div class="section-heading"><h2>${count(unplaced.length,'photo')} without a place</h2></div><div class="unplaced-grid">${unplaced.map(p=>`<button class="unplaced-card" data-action="locate" data-id="${p.id}"><img src="${esc(p.src)}" alt="${esc(p.caption)}"><span>＋ Add location</span></button>`).join('')}</div></section>`:''}<div class="composer-stops">${groups.map((s,i)=>`<section class="composer-stop"><header><span class="stop-index">${String(i+1).padStart(2,'0')}</span><div><h2>${esc(s.name)}</h2><p>${count(s.photos.length,'photo')}</p></div><div class="stop-order"><button data-action="move-stop" data-id="${s.id}" data-direction="-1" ${!i?'disabled':''} aria-label="Move ${esc(s.name)} earlier">↑</button><button data-action="move-stop" data-id="${s.id}" data-direction="1" ${i===groups.length-1?'disabled':''} aria-label="Move ${esc(s.name)} later">↓</button></div></header><div class="group-thumbs">${s.photos.map(p=>`<button data-action="locate" data-id="${p.id}" aria-label="Change location for ${esc(p.caption)}"><img src="${esc(p.src)}" alt="${esc(p.caption)}"></button>`).join('')}</div><button class="stop-memory-editor" data-action="draft-note" data-id="${s.id}">${icon(s.notes.length?'note':'plus')}<span>${s.notes.length?esc(s.notes[0]):'Add a note'}</span>${icon('edit')}</button></section>`).join('')}</div><details class="compose-extras"><summary>Grouping distance</summary><label class="group-radius" for="group-radius">Combine nearby photos<select id="group-radius">${[50,150,500].map(r=>`<option value="${r}" ${draft.radius===r?'selected':''}>${r} meters</option>`).join('')}</select></label></details>`,`<span class="footer-note">${count(groups.length,'stop')}</span><button class="button dark" data-action="create-next">Done ${icon('check')}</button>`);$('#group-radius').onchange=e=>{draft.radius=Number(e.target.value);composerPlaces()};}
function audienceName(value){return {private:'Only me',followers:'Followers',everyone:'Everyone'}[value]||'Only me';}
async function publishJourney(){collectStory();if(!draft?.photos.length){toast('Add a photo to continue.');return}draft.title=journeyName(draft.caption||'',draft.place||'');if((draft.start&&!draft.end)||(!draft.start&&draft.end)||(draft.start&&draft.end<draft.start)){toast('Choose both dates, with the last day after the first.');$('#journey-start').focus();return}draft.place||=getStops(draft)[0]?.name||'A journey to remember';const posted={...structuredClone(draft),author:'me',createdAt:new Date().toISOString()};journeys.unshift(posted);draft=null;editingDraft=false;createStep=1;const saved=await flushState();history.replaceState({atlasPrevious:'#/home'},'','#/home');go('journey',posted.id);returnScreen='home';toast(saved?'Your post is in your journal, saved on this device.':'Post created in this tab. Device storage is unavailable.');}
async function initApp(){try{const data=await readState();if(data?.version===1){journeys=data.journeys||[];sampleState=data.sampleState||sampleState;draft=data.draft||null;createStep=data.createStep||1;profile={...profile,...data.profile};savedIds=new Set(data.savedIds||[]);likedIds=new Set(data.likedIds||[]);following=new Set(data.following||[]);comments=data.comments||{};storyIds=data.storyIds||['kyoto','alps'];}}catch{storageWarned=true;}sampleState.author='me';sampleState.demo=true;sampleState.category='Coast';sampleState.audience||='private';window.addEventListener('hashchange',()=>{closeEditor();renderScreen();window.scrollTo(0,0)});window.addEventListener('popstate',()=>{closeEditor();renderScreen();window.scrollTo(0,0)});renderScreen();}

const demoSocial={sample:{likes:128,likedBy:['maya','alex'],comments:[{author:'maya',text:'That little cove is going straight on my list.'},{author:'alex',text:'The kind of trip you wish would last a little longer.'}]},kyoto:{likes:86,likedBy:['alex','maya'],comments:[{author:'alex',text:'Those quiet streets. Such a beautiful way to see Kyoto.'}]},alps:{likes:214,likedBy:['maya','alex'],comments:[{author:'maya',text:'A whole afternoon by that lake, please.'}]}};
let storyIds=['kyoto','alps'],storyIndex=0,storyJourneyId=null,connectionTab='followers';
function allComments(id){return [...(demoSocial[id]?.comments||[]),...(comments[id]||[])];}
function likesCount(id){return (demoSocial[id]?.likes||0)+(likedIds.has(id)?1:0);}
function socialActions(j){return `<div class="post-social"><div class="feed-like-group"><button class="reaction feed-like-toggle ${likedIds.has(j.id)?'liked':''}" data-action="like" data-id="${j.id}" aria-label="${likedIds.has(j.id)?'Unlike':'Like'} ${esc(j.place||'Journey')}" aria-pressed="${likedIds.has(j.id)}">${icon('heart')}</button><button class="feed-like-count" data-action="likes" data-id="${j.id}" aria-label="See who liked ${esc(j.place||'Journey')}"><span data-like-count="${esc(j.id)}">${likesCount(j.id)}</span></button></div><button class="reaction" data-action="comments" data-id="${j.id}" aria-label="Open comments on ${esc(j.place||'Journey')}">${icon('chat')}<span>${allComments(j.id).length}</span></button></div>`;}

function commentPreview(j){const c=allComments(j.id).at(-1);return `<button class="comment-peek" data-action="comments" data-id="${j.id}">${c?`<strong>${esc(person(c.author||'me').name.split(' ')[0])}</strong><span>${esc(c.text)}</span>`:'<span>Be the first to leave a thought…</span>'}</button>`;}
function commentItems(id){return allComments(id).map(c=>`<article class="comment">${avatar(person(c.author||'me'))}<div><strong>${esc(person(c.author||'me').name)}<small>${c.createdAt?'Just here':'Demo'}</small></strong><p>${esc(c.text)}</p></div></article>`).join('');}
function refreshCommentIndicators(id){const j=findJourney(id),latest=allComments(id).at(-1),total=allComments(id).length;if(!j)return;$$(`.post-social [data-action="comments"][data-id="${CSS.escape(id)}"] span,[data-comment-count="${CSS.escape(id)}"]`).forEach(el=>el.textContent=total);$$(`.detail-comment-count[data-id="${CSS.escape(id)}"]`).forEach(el=>el.setAttribute('aria-label',`Read ${total} comments on ${j.place||'this journey'}`));$$(`.comment-peek[data-id="${CSS.escape(id)}"]`).forEach(el=>el.innerHTML=latest?`<strong>${esc(person(latest.author||'me').name.split(' ')[0])}</strong><span>${esc(latest.text)}</span>`:'<span>Be the first to leave a thought…</span>');}
function likedByLine(j){const ids=[...(likedIds.has(j.id)?['me']:[]),...(demoSocial[j.id]?.likedBy||[])];if(!ids.length)return '<span>No likes yet.</span>';const names=ids.map(id=>person(id).name.split(' ')[0]),list=names.length===1?names[0]:`${names.slice(0,-1).join(', ')} and ${names.at(-1)}`;return `<span class="liked-by-avatars">${ids.map(id=>avatar(person(id))).join('')}</span><span>Liked by <strong>${esc(list)}</strong>${demoSocial[j.id]?' · Sample activity':''}</span>`;}
function detailConversation(j){return `<section class="detail-conversation"><div class="detail-social-row"><div class="detail-like-group"><button class="detail-like-toggle reaction ${likedIds.has(j.id)?'liked':''}" data-action="like" data-id="${esc(j.id)}" aria-label="${likedIds.has(j.id)?'Unlike':'Like'} ${esc(j.place||'Journey')}" aria-pressed="${likedIds.has(j.id)}">${icon('heart')}</button><button class="detail-like-count" data-action="likes" data-id="${esc(j.id)}" aria-label="See who liked ${esc(j.place||'Journey')}"><strong data-like-count="${esc(j.id)}">${likesCount(j.id)}</strong><span>likes</span></button></div><button class="detail-comment-count" data-action="comments" data-id="${esc(j.id)}" aria-label="Read ${allComments(j.id).length} comments on ${esc(j.place||'Journey')}">${icon('chat')}<span>Comments</span><strong data-comment-count="${esc(j.id)}">${allComments(j.id).length}</strong></button></div><button class="detail-liked-by" data-action="likes" data-id="${esc(j.id)}" data-liked-by="${esc(j.id)}" aria-label="See who liked ${esc(j.place||'Journey')}">${likedByLine(j)}</button></section>`;}
function followerIds(id){return {me:['maya','alex'],maya:['alex'],alex:['maya']}[id]||[];}
function renderConnections(id='me'){const p=person(id),ids=connectionTab==='followers'?followerIds(id):id==='me'?[...following]:['me'];pageMain(`<header class="page-intro"><span class="eyebrow">YOUR COMMUNITY</span><h1>Your people<span class="accent">.</span></h1></header><div class="connections-tabs"><button data-action="connection-tab" data-id="followers" data-person="${id}" class="${connectionTab==='followers'?'active':''}">${followerIds(id).length} followers</button><button data-action="connection-tab" data-id="following" data-person="${id}" class="${connectionTab==='following'?'active':''}">${id==='me'?following.size:1} following</button></div><div class="connection-list">${ids.map(pid=>{const v=person(pid);return `<article class="connection-row"><button class="author-link" data-action="author" data-id="${pid}">${avatar(v)}<span><strong>${esc(v.name)}</strong><small>@${esc(v.handle)}</small></span></button>${pid!=='me'?`<button class="button ${following.has(pid)?'glass':'dark'}" data-action="follow" data-id="${pid}">${following.has(pid)?'Following':'Follow'}</button>`:''}</article>`}).join('')||'<p class="muted">Find people whose journeys inspire you.</p>'}</div><p class="local-footnote">Demo community. Connections are stored on this device.</p>`,'app-page connections-page');}
function renderEditProfile(){pageMain(`<header class="identity-heading"><button class="text-button" data-action="nav" data-id="profile">${icon('back')}Your profile</button><span class="overline">THE PERSON BEHIND THE PLACES</span><h1>Make yourself<br>at home.</h1></header><div class="identity-edit-layout"><aside class="identity-note">${avatar(profile)}<h2>Your traveler’s ID.</h2><p>A name, a home base, a little about you. This is your corner of Atlas.</p><small>Stored on this device.</small></aside><form id="profile-form" class="profile-edit-form"><div class="field"><label for="profile-name">Name</label><input id="profile-name" maxlength="50" required value="${esc(profile.name)}"></div><div class="field"><label for="profile-handle">Username</label><input id="profile-handle" pattern="[A-Za-z0-9_]{3,24}" title="3–24 letters, numbers, or underscores" required value="${esc(profile.handle)}"></div><div class="field"><label for="profile-bio">Bio</label><textarea id="profile-bio" rows="3" maxlength="180">${esc(profile.bio)}</textarea></div><div class="field"><label for="profile-location">Home base</label><input id="profile-location" maxlength="80" value="${esc(profile.location)}"></div><button class="button dark" type="submit">Save changes ${icon('check')}</button></form></div>`,'workspace edit-profile-page');$('#profile-form').onsubmit=e=>{e.preventDefault();const name=$('#profile-name').value.trim();if(!name)return;profile={...profile,name,handle:$('#profile-handle').value.trim(),bio:$('#profile-bio').value.trim(),location:$('#profile-location').value.trim(),initials:name.split(/\s+/).slice(0,2).map(s=>s[0]).join('')};persist();go('profile');toast('Profile updated.');};}

function addStory(){const mine=journeys.filter(ownJourney);modal('Add a story',`<h2>A glimpse of your journey.</h2><p class="modal-description">Choose a journey to add to your stories.</p><div class="story-picker">${mine.map(j=>`<button data-action="publish-story" data-id="${j.id}"><img src="${coverPhoto(j).src}" alt=""><span>${esc(j.place||'Journey')}<small>${count(j.photos.length,'photo')}</small></span>${icon('plus')}</button>`).join('')}</div><button class="text-link" data-action="create">${icon('plus')}Start a new journey</button><p class="local-footnote">Stories are a local preview.</p>`,'');}
function openStory(id,index=0){const j=findJourney(id);if(!j?.photos.length)return;storyJourneyId=id;storyIndex=Math.max(0,Math.min(index,j.photos.length-1));const photo=j.photos[storyIndex];modal('Travel story',`<div class="story-viewer"><img class="story-full-image" src="${esc(photo.src)}" alt="${esc(photo.caption||j.caption||j.place)}"><div class="story-shade"></div><div class="story-progress">${j.photos.map((p,i)=>`<span class="${i<=storyIndex?'seen':''}"></span>`).join('')}</div><button class="story-author" data-action="author" data-id="${j.author||'me'}">${avatar(person(j.author))}<span>${esc(person(j.author).name)}<small>${esc(j.place)}</small></span></button><button class="story-dismiss" data-action="close-editor" aria-label="Close story">${icon('close')}</button><div class="story-controls"><button data-action="story-prev" aria-label="Previous story photo" ${!storyIndex?'disabled':''}>${icon('back')}</button><button data-action="story-next" aria-label="Next story photo" ${storyIndex===j.photos.length-1?'disabled':''}>${icon('back','chevron-forward')}</button></div><div class="story-bottom"><p>${esc(photo.caption||j.caption||j.place)}</p><button class="button glass" data-action="open-journey" data-id="${j.id}">View journey ${icon('route')}</button></div></div>`,'');$('#editor').classList.add('story-modal');}
function openCoverPicker(){collectStory();modal('Choose cover',`<h2>Choose your cover.</h2><div class="cover-select cover-grid">${draft.photos.map(p=>`<button data-action="choose-cover" data-id="${p.id}" aria-label="Use ${esc(p.caption||'photo')} as cover" aria-pressed="${draft.cover===p.id}" class="${draft.cover===p.id?'chosen':''}"><img src="${esc(p.src)}" alt="${esc(p.caption||'Cover choice')}"></button>`).join('')}</div>`,`<button class="button dark" data-action="cover-done">Done ${icon('check')}</button>`);}

document.addEventListener('submit',e=>{if(e.target.id!=='sheet-comment-form')return;e.preventDefault();const id=e.target.dataset.journey,text=e.target.querySelector('textarea').value.trim();if(!text||!findJourney(id))return;(comments[id]??=[]).push({text,author:'me',createdAt:new Date().toISOString()});persist();refreshCommentIndicators(id);showComments(id);$('#editor .modal-content').scrollTop=$('#editor .modal-content').scrollHeight;$('#sheet-comment-text').focus();toast('Thought added to the conversation.');});

document.addEventListener('click',async e=>{if(e.target.closest('.skip-link')){e.preventDefault();$('#journey').focus();return}const v=e.target.closest('[data-view]');if(v){changeView(v.dataset.view);return}const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const a=el.dataset.action,id=el.dataset.id;
 if(a==='discovery-audience'){feedTab=id;renderExplore();}
 if(a==='studio-cover'){draft.cover=id;renderCreatePhotos();}
 if(a==='sample-stop'){go('journey','sample');openStop(id);}
 if(a==='reader-stop'){document.getElementById('chapter-'+id)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
 if(a==='share-post'){const chosen=findJourney(id);if(chosen){journey=structuredClone(chosen);share();}}
 if(a==='nav'){if(id==='explore'){searchQuery='';exploreCategory='All';feedTab='all'}if(id==='profile')profileTab='journeys';go(id);}
 if(a==='toolbar-back'){if(history.state?.atlasPrevious)history.back();else if(screen==='connections')go('profile',routeFromHash().id||'me');else if(['saved','editprofile'].includes(screen))go('profile');else go('home');}
 if(a==='return-feed')go(returnScreen==='create'?'home':returnScreen||'home');
 if(a==='author'){profileTab='journeys';go('profile',id);}
 if(a==='feed-stop'){const y=window.scrollY,stopId=el.dataset.stop;feedExpandedStop=feedExpandedStop?.journeyId===id&&feedExpandedStop.stopId===stopId?null:{journeyId:id,stopId};if(screen==='explore')renderSearchResults();else renderHome();window.scrollTo(0,y);}
 if(a==='feed-tab'){const y=window.scrollY;feedTab=id;renderHome();window.scrollTo(0,y);}
 if(a==='feed-category'){feedCategory=id;renderHome();}
 if(a==='explore-category'){exploreCategory=id;renderExplore();}
 if(a==='explore-focus')focusExplore(id);
 if(a==='explore-reset')resetExploreMap();
 if(a==='clear-explore'){searchQuery='';exploreCategory='All';feedTab='all';renderExplore();}
 if(a==='search-destination'){searchQuery=id;exploreCategory='All';go('explore');}
 if(a==='toggle-save'){if(savedIds.has(id))savedIds.delete(id);else savedIds.add(id);persist();renderScreen();toast(savedIds.has(id)?'Kept on your someday shelf.':'Journey removed from Saved.');}
 if(a==='like'){if(likedIds.has(id))likedIds.delete(id);else likedIds.add(id);persist();$$('[data-action="like"]').filter(b=>b.dataset.id===id).forEach(b=>{b.classList.toggle('liked',likedIds.has(id));b.setAttribute('aria-pressed',likedIds.has(id));b.setAttribute('aria-label',`${likedIds.has(id)?'Unlike':'Like'} ${findJourney(id).place||'Journey'}`);b.innerHTML=icon('heart')+((b.classList.contains('detail-like-toggle')||b.classList.contains('feed-like-toggle'))?'':'<span>'+likesCount(id)+'</span>');});$$('[data-like-count]').filter(b=>b.dataset.likeCount===id).forEach(b=>b.textContent=likesCount(id));$$('[data-liked-by]').filter(b=>b.dataset.likedBy===id).forEach(b=>b.innerHTML=likedByLine(findJourney(id)));}
 if(a==='likes')showLikes(id);
 if(a==='comments')showComments(id);
 if(a==='follow'){if(following.has(id))following.delete(id);else following.add(id);persist();if($('#editor').open)showFollowing();else renderScreen();toast(following.has(id)?`Following ${person(id).name}.`:`Unfollowed ${person(id).name}.`);}
 if(a==='profile-tab'){profileTab=id;renderProfile(el.dataset.person||'me');}
 if(a==='profile-photo'){go('journey',el.dataset.journey);openPhoto(id);}
 if(a==='edit-profile')editProfile();
 if(a==='following-list')showFollowing();
 if(a==='connections'){connectionTab=el.dataset.tab;go('connections',id)}
 if(a==='connection-tab'){connectionTab=id;renderConnections(el.dataset.person)}
 if(a==='add-story')addStory();
 if(a==='story')openStory(id);
 if(a==='publish-story'){storyIds=[id,...storyIds.filter(s=>s!==id)];persist();renderHome();openStory(id);}
 if(a==='story-next')openStory(storyJourneyId,storyIndex+1);
 if(a==='story-prev')openStory(storyJourneyId,storyIndex-1);
 if(a==='cover-picker')openCoverPicker();
 if(a==='cover-done'){closeEditor();createStory();}
 if(a==='settings')modal('Your settings',`<span class="eyebrow">YOUR WORLD, YOUR WAY</span><h2>A little <em>housekeeping.</em></h2><div class="settings-row">${icon('person')}<div><strong>Your profile</strong><p>Your name, bio, and home base.</p></div><button class="button glass" data-action="edit-profile">Edit</button></div><div class="settings-row">${icon('lock')}<div><strong>Saved on this device</strong><p>Your journeys, drafts, bookmarks, and profile are stored in this browser. This prototype has no account or cloud sync.</p></div></div><div class="settings-row">${icon('globe')}<div><strong>Sharing is a preview</strong><p>No posts, photos, follows, or comments are sent to other users.</p></div></div>`,`<span class="muted">Atlas · Design preview</span><button class="button dark" data-action="close-editor">Done</button>`);
 if(a==='use-demo'){collectStory();samplePhotos.forEach(p=>{if(!draft.photos.some(d=>d.id===p.id)){draft.photos.push(structuredClone(p));if(sampleAnnotations[p.id])draft.annotations[p.id]=structuredClone(sampleAnnotations[p.id]);}});draft.cover||='p2';draft.place||='Amalfi Coast, Italy';draft.title||='A little closer to la dolce vita.';draft.caption||=sampleJourney.caption;renderCreatePhotos();toast('Sample photos added. Review your story and cover.');}
 if(a==='remove-draft-photo'){collectStory();draft.photos=draft.photos.filter(p=>p.id!==id);delete draft.annotations[id];if(draft.cover===id)draft.cover=draft.photos[0]?.id||null;renderCreatePhotos();}
 if(a==='save-draft'){collectStory();const saved=await flushState();go('home');toast(saved?'Draft saved. Continue from your journal whenever you’re ready.':'Draft is in this tab only. Device storage is unavailable.');}
 if(a==='review-places'){collectStory();createStep=2;composerPlaces();window.scrollTo(0,0);}
 if(a==='move-stop'){const groups=getStops(draft),from=groups.findIndex(s=>s.id===id),to=from+Number(el.dataset.direction);if(from>=0&&to>=0&&to<groups.length){[groups[from],groups[to]]=[groups[to],groups[from]];draft.stopOrder=groups.map(s=>s.id);composerPlaces();}}
 if(a==='stop')openStop(id);
 if(a==='close-stop')$('#stop-sheet').close();
 if(a==='close-editor')closeEditor();
 if(a==='close-lightbox')$('#lightbox').close();
 if(a==='collection')showCollection();
 if(a==='saved')showCollection(true);
 if(a==='save'){if(savedIds.has(journey.id))savedIds.delete(journey.id);else savedIds.add(journey.id);render();toast(savedIds.has(journey.id)?'Journey saved':'Journey removed from saved');}
 if(a==='share')share();
 if(a==='gallery')showGallery();
 if(a==='organize'&&ownJourney()){editingDraft=false;organize(false);}
 if(a==='organize-draft'){editingDraft=true;createStep=2;composerPlaces();}
 if(a==='done-organize'){closeEditor();render();}
 if(a==='edit-note'&&ownJourney())openNote(id,false);
 if(a==='draft-note')openNote(id,true);
 if(a==='locate'){editingDraft=screen==='create';if(editingDraft||ownJourney())openLocation(id);}
 if(a==='choose-place'){const s=getStops(activeJourney()).find(s=>s.id===id);if(s){chooseLocation(s.gps,s.name);$$('.location-choices button').forEach(b=>b.classList.toggle('chosen',b===el));}}
 if(a==='show-on-map'){$('#stop-sheet').close();selectedId=id;render();$('.journey-canvas').scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
 if(a==='canvas-fit')$('.journey-canvas').scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
 if(a==='zoom-in')map?.zoomIn();if(a==='zoom-out')map?.zoomOut();if(a==='fit-map')fitMap();
 if(a==='map-notes'){showMapNotes=!showMapNotes;el.innerHTML=icon('note')+'Notes '+(showMapNotes?'on':'off');el.setAttribute('aria-pressed',showMapNotes);renderMapMarkers();}
 if(a==='photo')openPhoto(id);
 if(a==='photo-prev'&&lightboxIndex>0){lightboxIndex--;renderLightbox();}
 if(a==='photo-next'&&lightboxIndex<lightboxIds.length-1){lightboxIndex++;renderLightbox();}
 if(a==='photo-location'&&ownJourney()){$('#lightbox').close();$('#stop-sheet').close();editingDraft=false;openLocation(id);}
 if(a==='add-to-stop'&&ownJourney()){const s=stops.find(s=>s.id===id);editingDraft=false;modal('Add photos to stop',`<h2>More of <em>${esc(s.name)}.</em></h2><p class="modal-description">Photos without GPS tags will be placed here. Photos with GPS tags keep their own location.</p>${uploadMarkup()}`);bindUpload(s);}
 if(a==='create')go('create');
 if(a==='pick-sample'){const at=draft.photos.findIndex(p=>p.id===id);if(at>=0){draft.photos.splice(at,1);delete draft.annotations[id];if(draft.cover===id)draft.cover=draft.photos[0]?.id||null}else{draft.photos.push(structuredClone(samplePhotos.find(p=>p.id===id)));if(sampleAnnotations[id])draft.annotations[id]=structuredClone(sampleAnnotations[id]);draft.cover||=id;}renderCreatePhotos();}
 if(a==='create-next')nextCreate();
 if(a==='create-back'){collectStory();if(createStep===3)composerPlaces();else renderCreatePhotos();window.scrollTo(0,0);}
 if(a==='delete-draft')modal('Delete draft',`<h2>Delete this draft?</h2><p class="modal-description">Its photos, places, and writing will be removed from this device.</p>`,`<button class="text-button" data-action="close-editor">Keep draft</button><button class="button danger" data-action="confirm-delete-draft">Delete draft</button>`);
 if(a==='confirm-delete-draft'){draft=null;createStep=1;editingDraft=false;closeEditor();await flushState();go('home');toast('Draft deleted.');}
 if(a==='choose-cover'){draft.cover=id;$$('.cover-select button').forEach(b=>{b.classList.toggle('chosen',b===el);b.setAttribute('aria-pressed',b===el)});const img=$('#chosen-cover-preview');if(img)img.src=coverPhoto(draft).src;persist();}
 if(a==='post'){closeEditor();publishJourney();}
 if(a==='open-journey')go('journey',id);
 if(a==='profile')go('profile');
 if(a==='copy-link'){try{await navigator.clipboard.writeText(location.origin+location.pathname+'#/journey/'+encodeURIComponent(journey.id));toast('Preview link copied');closeEditor();}catch{toast('Copy this page’s address from the browser.');}}
});
for(const d of $$('dialog')){d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){if(d.id==='editor')closeEditor();else d.close();}});}
$('#editor').addEventListener('cancel',()=>{if(editingDraft&&$('#story-form'))collectStory();persist();editingDraft=screen==='create';});
let lastMobile=window.matchMedia('(max-width:700px)').matches;window.addEventListener('resize',()=>{const mobile=window.matchMedia('(max-width:700px)').matches;if(mobile!==lastMobile){lastMobile=mobile;const scene=$('#route-scene');if(scene)scene.innerHTML=journeyCanvas();}locationMap?.invalidateSize();});
initApp();
if(document.modelContext?.registerTool){const ctrl=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:ctrl.signal})).catch(()=>{})}catch{}};register({name:'open_journey_stop',title:'Open a stop’s photos and notes',description:'Open the selected journey stop in a bottom sheet.',inputSchema:{type:'object',properties:{index:{type:'integer',minimum:0}},required:['index'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!Number.isInteger(input.index)||!stops[input.index])throw Error('Choose an existing stop.');openStop(stops[input.index].id);return {name:stops[input.index].name,photos:stops[input.index].photos.length,notes:stops[input.index].notes}}});register({name:'open_photo_organizer',title:'Organize journey photos',description:'Show photos grouped by location and photos that need a location. This does not upload or post anything.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(){organize(false);return {stops:stops.length,unplaced:journey.photos.filter(p=>!validGPS(p.gps)).length}}});window.addEventListener('pagehide',()=>ctrl.abort(),{once:true});}
